mapper.select:
SELECT IPHTML_NO, IPROM_NO, SITEM, STITLE, SCONTENTS, SREASON,
       SGAEJUNG_TYPE, SDISP_YN, SSTART_DT, SINS_DT, SSEARCH_TEXT, SSYS_ID
  FROM TB_PROV_HTML
 WHERE IPROM_NO = #{promNo}
   AND SITEM    = #{item}

SELECT COUNT(*)
  FROM TB_PROV_HTML H, TB_PROM P
 WHERE H.IPROM_NO = P.IPROM_NO
   AND P.ILAW_ID  = ( SELECT ILAW_ID FROM TB_PROM WHERE IPROM_NO = #{promNo} )
   AND H.SITEM    = #{item}

   AND H.IPHTML_NO  !=  #{exceptProvHtmlNo}
